def f(g):
    from collections import Counter
    cnt=Counter(x for r in g for x in r)
    bg=cnt.most_common(1)[0][0]
    items=list(cnt.items()); items.sort(key=lambda kv:-kv[1])
    bdr=items[1][0]; acc=items[-1][0]
    # flood from accent, fill cells until hitting border/boundary
    H,W=len(g),len(g[0])
    out=[row[:] for row in g]
    seen=set(); stack=[]
    for r in range(H):
        for c in range(W):
            if (out[r][c]==acc) and (r,c) not in seen:
                stack=[(r,c)]; seen.add((r,c))
                while stack:
                    y,x=stack.pop()
                    out[y][x]=4
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and out[ny][nx]!=bdr and (ny,nx) not in seen:
                            seen.add((ny,nx)); stack.append((ny,nx))
    return out
