def components(g):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; res=[]
    for r in range(H):
        for c in range(W):
            if not seen[r][c] and g[r][c]!=min(set(x for row in g for x in row),key=lambda v:sum(row.count(v) for row in g)):
                continue
    # simpler: collect colors, bg = most frequent
    from collections import Counter
    cnt=Counter(x for row in g for x in row)
    bg=max(cnt,key=cnt.get)
    cells=[(r,c,g[r][c]) for r in range(H) for c in range(W) if g[r][c]!=bg]
    comps={}
    for (r,c,v) in cells:
        comps.setdefault((v,),[]).append((r,c))
    return bg,comps
