def comps_of(g):
    from collections import Counter
    cnt=Counter(x for row in g for x in row); bg=max(cnt,key=cnt.get)
    H=len(g); W=len(g[0])
    seen=set(); res=[]
    for r in range(H):
        for c in range(W):
            if (r,c) in seen: continue
            v=g[r][c]
            if v==bg: continue
            stack=[(r,c)]; comp=[]
            while stack:
                x,y=stack.pop()
                if (x,y) in seen: continue
                seen.add((x,y))
                comp.append((x,y,v))
                for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                    stack.append((x+dr,y+dc))
            res.append(comp)
    return bg,res
for i in [1,2,3,4]:
    inp=G[f'Demo pair {i} input']; out=G[f'Demo pair {i} output']
    bg,comp=comps_of(inp)
    seeds=[];walls=[]
    for c in comp:
        if len(c)==1: seeds.append(c[0][:2])
        else: walls.append(c)
    print(i,'bg',bg)
    print('  seeds',seeds)
    print('  walls',[([x[2] for x in c], sorted(set(r for r,_ in c)),len(c)) for c in walls])

